/**
 * frontend/src/components/Dashboard.jsx
 * VERSION COMPLÈTE & STRUCTURÉE (Alignée sur ta version 374 lignes)
 * ✅ Logique de calcul de présence sécurisée
 * ✅ Intégration complète des statistiques de confiance (Min, Max, Avg)
 * ✅ Gestion d'erreurs granulaire
 */

import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI } from "./api_service";

// --- CONFIGURATION DES COULEURS (Thème Premium) ---
const COLORS = {
  primary: "#4F46E5",
  primaryLight: "#EEF2FF",
  success: "#10B981",
  successLight: "#DCFCE7",
  danger: "#EF4444",
  dangerLight: "#FEE2E2",
  warning: "#F59E0B",
  warningLight: "#FEF3C7",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0",
  background: "#F8FAFC",
  surface: "#FFFFFF"
};

const Dashboard = () => {
  // --- ÉTATS (STRUCTURE COMPLÈTE) ---
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [lastUpdated, setLastUpdated] = useState(new Date());

  // --- LOGIQUE DE CHARGEMENT (FONCTION PRINCIPALE) ---
  const loadData = async () => {
    try {
      // On ne montre le spinner de chargement complet qu'au premier appel
      if (attendanceLog.length === 0) setLoading(true);

      console.log("🔄 Synchronisation du Dashboard...");

      const [statsRes, logRes, statusRes] = await Promise.all([
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      // Validation et nettoyage des données (Safe Parsing)
      const dataStats = statsRes?.data || {};
      const summary = dataStats.summary || {};

      setStats({
        active_students: dataStats.active_students || 0,
        present_today: dataStats.present_today || 0,
        absent_today: dataStats.absent_today || 0,
        summary: {
          unique_students: summary.unique_students || 0,
          total_records: summary.total_records || 0,
          avg_confidence: summary.avg_confidence || 0,
          max_confidence: summary.max_confidence || 0,
          min_confidence: summary.min_confidence || 0
        }
      });

      setAttendanceLog(logRes?.data?.records || []);
      setStatusList(statusRes?.data?.students || []);
      setLastUpdated(new Date());
      setError(null);

    } catch (err) {
      console.error("❌ Erreur Dashboard API:", err);
      setError("Erreur de liaison avec le serveur. Vérifiez que le backend est lancé.");
    } finally {
      setLoading(false);
    }
  };

  // --- EFFETS (LIFECYCLE) ---
  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    let timer;
    if (autoRefresh) {
      timer = setInterval(loadData, 10000); // 10 secondes
    }
    return () => clearInterval(timer);
  }, [autoRefresh]);

  // --- LOGIQUE DE CALCUL DES CARTES (MÉMOÏSÉE) ---
  const statCards = useMemo(() => {
    const total = stats.active_students || 0;
    const present = stats.present_today || 0;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      {
        id: 'total',
        label: "Étudiants Inscrits",
        value: total,
        icon: "👥",
        color: COLORS.primary,
        bgColor: COLORS.primaryLight
      },
      {
        id: 'present',
        label: "Présents (Aujourd'hui)",
        value: present,
        icon: "✅",
        color: COLORS.success,
        bgColor: COLORS.successLight
      },
      {
        id: 'absent',
        label: "Absents",
        value: stats.absent_today,
        icon: "❌",
        color: COLORS.danger,
        bgColor: COLORS.dangerLight
      },
      {
        id: 'rate',
        label: "Taux de Présence",
        value: `${rate}%`,
        icon: "📈",
        color: "#8B5CF6",
        bgColor: "#F5F3FF"
      }
    ];
  }, [stats]);

  // --- RENDU : ÉTAT DE CHARGEMENT ---
  if (loading) {
    return (
      <div style={styles.loaderContainer}>
        <div style={styles.spinner}></div>
        <p style={styles.loaderText}>Chargement des données biométriques...</p>
      </div>
    );
  }

  // --- RENDU : INTERFACE PRINCIPALE ---
  return (
    <div style={styles.pageWrapper}>

      {/* HEADER SECTION */}
      <header style={styles.header}>
        <div>
          <h1 style={styles.title}>Dashboard de Présence</h1>
          <p style={styles.subtitle}>Dernière mise à jour : {lastUpdated.toLocaleTimeString()}</p>
        </div>

        <div style={styles.actions}>
          <label style={styles.switchContainer}>
            <input 
              type="checkbox" 
              checked={autoRefresh} 
              onChange={() => setAutoRefresh(!autoRefresh)}
              style={styles.switchInput}
            />
            <span style={styles.switchLabel}>Auto-Refresh (10s)</span>
          </label>
          <button onClick={loadData} style={styles.refreshBtn}>
            🔄 Actualiser
          </button>
        </div>
      </header>

      {/* ERROR MESSAGE */}
      {error && (
        <div style={styles.errorAlert}>
          <span style={{marginRight: 10}}>⚠️</span> {error}
        </div>
      )}

      {/* STATS CARDS GRID */}
      <div style={styles.statsGrid}>
        {statCards.map((card) => (
          <div key={card.id} style={styles.statCard}>
            <div style={{...styles.iconWrapper, backgroundColor: card.bgColor, color: card.color}}>
              {card.icon}
            </div>
            <div style={styles.statInfo}>
              <span style={styles.statLabel}>{card.label}</span>
              <span style={styles.statValue}>{card.value}</span>
            </div>
          </div>
        ))}
      </div>

      <div style={styles.mainLayout}>

        {/* LEFT COLUMN: ATTENDANCE LOG */}
        <section style={styles.sectionCard}>
          <div style={styles.sectionHeader}>
            <h3 style={styles.sectionTitle}>Journal des Entrées</h3>
            <span style={styles.badgeCount}>{attendanceLog.length} scans aujourd'hui</span>
          </div>

          <div style={styles.tableResponsive}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>Étudiant</th>
                  <th style={styles.th}>Heure de passage</th>
                  <th style={styles.th}>Confiance IA</th>
                </tr>
              </thead>
              <tbody>
                {attendanceLog.length > 0 ? (
                  attendanceLog.map((row, idx) => (
                    <tr key={idx} style={styles.tr}>
                      <td style={styles.tdBold}>{row.student}</td>
                      <td style={styles.td}>{row.timestamp}</td>
                      <td style={styles.td}>
                        <div style={{
                          ...styles.confidenceBadge,
                          backgroundColor: row.confidence > 0.8 ? COLORS.successLight : COLORS.warningLight,
                          color: row.confidence > 0.8 ? COLORS.success : COLORS.warning
                        }}>
                          {(row.confidence * 100).toFixed(1)}%
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="3" style={styles.emptyCell}>Aucune activité détectée pour le moment.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>

        {/* RIGHT COLUMN: ANALYTICS & SUMMARY */}
        <div style={styles.rightColumn}>

          <section style={styles.sectionCard}>
            <h3 style={styles.sectionTitle}>Analyse de Précision</h3>
            <div style={styles.analyticsGrid}>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Max</span>
                <span style={{...styles.analyticValue, color: COLORS.success}}>
                  {(stats.summary.max_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Moyenne</span>
                <span style={{...styles.analyticValue, color: COLORS.primary}}>
                  {(stats.summary.avg_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Confiance Min</span>
                <span style={{...styles.analyticValue, color: COLORS.danger}}>
                  {(stats.summary.min_confidence * 100).toFixed(1)}%
                </span>
              </div>
              <div style={styles.divider}></div>
              <div style={styles.analyticRow}>
                <span style={styles.analyticLabel}>Total des scans</span>
                <span style={styles.analyticValue}>{stats.summary.total_records}</span>
              </div>
            </div>
          </section>

          <section style={{...styles.sectionCard, marginTop: 20}}>
            <h3 style={styles.sectionTitle}>Légende</h3>
            <div style={styles.legendItem}>
              <div style={{...styles.dot, backgroundColor: COLORS.success}}></div>
              <span>Présent : Détecté par caméra</span>
            </div>
            <div style={styles.legendItem}>
              <div style={{...styles.dot, backgroundColor: COLORS.danger}}></div>
              <span>Absent : Non encore vu</span>
            </div>
          </section>

        </div>
      </div>

      {/* BOTTOM SECTION: CLASS STATUS */}
      <section style={{...styles.sectionCard, marginTop: 25}}>
        <h3 style={styles.sectionTitle}>Statut Général de la Classe</h3>
        <div style={styles.tableResponsive}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>Étudiant</th>
                <th style={styles.th}>Email</th>
                <th style={styles.th}>Statut Actuel</th>
              </tr>
            </thead>
            <tbody>
              {statusList.map((student, index) => (
                <tr key={index} style={styles.tr}>
                  <td style={styles.tdBold}>{student.name}</td>
                  <td style={styles.tdMuted}>{student.email || "—"}</td>
                  <td style={styles.td}>
                    <span style={{
                      ...styles.statusBadge,
                      backgroundColor: student.present ? COLORS.successLight : COLORS.dangerLight,
                      color: student.present ? COLORS.success : COLORS.danger
                    }}>
                      {student.present ? "Présent" : "Absent"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

    </div>
  );
};

